import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import formatIpLocation from '../utils/formatIpLocation';
export default class IpLocationLabel extends Component {
  view() {
    const label = formatIpLocation(this.attrs.location);
    const plain = this.attrs.plain === true;
    return m("span", {
      className: "Post-ipLocation",
      title: app.translator.trans('ffans-ip-location.forum.tooltip')
    }, plain ? label : app.translator.trans('ffans-ip-location.forum.published_in', {
      location: label
    }));
  }
}
flarum.reg.add('ffans-ip-location', 'forum/components/IpLocationLabel', IpLocationLabel);